const COSTUME_ITEMS=[{id:'classic',name:'Classic Field Gear',cost:0,level:1,rarity:'STANDARD',colour:'#9bb5bc'},{id:'ranger',name:'Woodland Ranger',cost:600,level:3,rarity:'UNCOMMON',colour:'#8eac78'},{id:'pilot',name:'Aero Expedition Jacket',cost:1800,level:10,rarity:'RARE',colour:'#79b9ce'},{id:'cyber',name:'Circuit Sentinel',cost:5500,level:25,rarity:'EPIC',colour:'#7fe4df'},{id:'royal',name:'Astral Commander',cost:14000,level:50,rarity:'LEGENDARY',colour:'#e7cb81'},{id:'christmas',name:'Winter Star Expedition',cost:22000,level:20,rarity:'CHRISTMAS COLLECTION',colour:'#e69d98'}];
const ACCESSORY_ITEMS=[{id:'none',name:'Your classic accessory',cost:0,level:1,rarity:'STANDARD',colour:'#9bb5bc'},{id:'scarf',name:'Trail Scarf',cost:450,level:1,rarity:'UNCOMMON',colour:'#dea87c'},{id:'visor',name:'Recon Visor',cost:1600,level:8,rarity:'RARE',colour:'#93dce4'},{id:'halo',name:'Orbital Energy Halo',cost:6500,level:30,rarity:'EPIC',colour:'#aadce7'},{id:'helmet',name:'Deepwater Flight Helmet',cost:9500,level:40,rarity:'EPIC',colour:'#bdd6d4'},{id:'antlers',name:'Starlight Antlers',cost:12000,level:15,rarity:'CHRISTMAS COLLECTION',colour:'#e2c17f'}];
function equippedCosmetic(){const value=profile.cosmetics||{},inv=shopInventory();return{outfit:COSTUME_ITEMS.some(i=>i.id===value.outfit&&playerLevel()>=i.level&&(i.id==='classic'||inv['costume:'+i.id]))?value.outfit:'classic',accessory:ACCESSORY_ITEMS.some(i=>i.id===value.accessory&&playerLevel()>=i.level&&(i.id==='none'||inv['accessory:'+i.id]))?value.accessory:'none'}}
function cosmeticForHero(h){return h.cosmetic||equippedCosmetic()}
function costumeArt(style){const outfit=style?.outfit||'classic',accessory=style?.accessory||'none';let art='';if(outfit==='ranger')art+='<path d="M76 147L104 158 117 158 145 147 156 192Q111 206 67 192Z" fill="#536b4d" stroke="#253b35" stroke-width="3"/><path d="M111 158V195M77 178H98V189H77M124 178H145V189H124" fill="none" stroke="#a8b590" stroke-width="3"/>';if(outfit==='pilot')art+='<path d="M77 146L104 157H118L145 147 157 193Q111 210 66 193Z" fill="#315d75" stroke="#203c51" stroke-width="3"/><path d="M78 146L101 172 111 163 121 172 145 147" fill="#b6c5c0"/><path d="M111 167V200M76 179L98 176M126 176L147 180" stroke="#a3cbd2" stroke-width="3"/>';if(outfit==='cyber')art+='<path d="M77 148L106 158 118 158 145 147 155 194Q111 207 68 194Z" fill="#192f44" stroke="#75d6d5" stroke-width="2"/><path d="M84 159L88 181 104 189M139 159L135 181 120 189M111 160V197" fill="none" stroke="#79dfdf" stroke-width="3"/><circle cx="111" cy="179" r="6" fill="#dbfff2"/>';if(outfit==='royal')art+='<path d="M75 146L104 158H119L146 146 160 199Q111 216 63 199Z" fill="#29394f" stroke="#d3ba7c" stroke-width="3"/><path d="M79 148L142 196 132 201 72 159Z" fill="#c4a96c"/><path d="M74 190Q111 204 149 190M111 161V191" fill="none" stroke="#d5c58e" stroke-width="2"/>';if(outfit==='christmas')art+='<path d="M76 147L105 158H119L146 147 157 197Q111 213 65 197Z" fill="#a44245" stroke="#3a3c48" stroke-width="3"/><path d="M110 159V202M69 196Q111 210 153 196" fill="none" stroke="#e5e8d6" stroke-width="9"/><path d="M69 185Q111 196 153 185" fill="none" stroke="#263a3e" stroke-width="9"/><rect x="103" y="185" width="17" height="12" rx="2" fill="none" stroke="#d8bd7d" stroke-width="3"/><path d="M72 53Q84 5 118 26L151 45Q162 49 157 59L111 47Z" fill="#a44245" stroke="#3a3c48" stroke-width="3"/><path d="M71 53Q111 38 153 55" fill="none" stroke="#edf0df" stroke-width="12"/><circle cx="157" cy="58" r="9" fill="#edf0df"/>';
 if(accessory==='scarf')art+='<path d="M77 143Q110 157 144 143L140 156Q111 169 80 155Z" fill="#b67558" stroke="#493e40" stroke-width="2"/><path d="M123 158L136 157 141 187 127 184Z" fill="#d0a178"/>';if(accessory==='visor')art+='<path d="M67 85Q111 74 156 86L151 103Q111 113 72 102Z" fill="#63b6c2" fill-opacity=".48" stroke="#b6e6e6" stroke-width="3"/><path d="M78 88L102 84" stroke="#e5ffff" stroke-width="3"/>';if(accessory==='halo')art+='<ellipse cx="111" cy="22" rx="42" ry="10" fill="none" stroke="#8edce1" stroke-width="5"/><ellipse cx="111" cy="22" rx="45" ry="12" fill="none" stroke="#d8fff1" stroke-width="1.5"/>';if(accessory==='helmet')art+='<path d="M48 96Q44 21 111 21Q179 21 175 98L165 131Q111 156 58 131Z" fill="#9be7ee" fill-opacity=".09" stroke="#b9d5d9" stroke-width="7"/><path d="M60 71Q73 37 107 34" stroke="#e6fcfa" stroke-width="4" fill="none"/><path d="M62 132Q111 150 161 132" fill="none" stroke="#547f96" stroke-width="10"/>';if(accessory==='antlers')art+='<g fill="none" stroke="#c2a171" stroke-width="6" stroke-linecap="round"><path d="M77 48L59 28 60 8M62 31L43 25 37 15M59 20L47 7M146 47L163 27 162 8M162 30L179 23 184 12M162 18L174 5"/></g><circle cx="43" cy="25" r="4" fill="#d8e6a6"/><circle cx="178" cy="23" r="4" fill="#de9b8a"/>';return '<g data-cosmetic-outfit="'+outfit+'" data-cosmetic-accessory="'+accessory+'">'+art+'</g>'}
const costumedHeroSVG=heroSVG;heroSVG=function(id,extra='',look,weapon,equipment,forcedCosmetic){return costumedHeroSVG(id,extra,look,weapon,equipment).replace('</svg>',costumeArt(forcedCosmetic||equippedCosmetic())+'</svg>')};
function buyCosmetic(kind,id){if(!canVisitOutfitShop()){toast('Visit the outfit shop between rounds.');return false}const list=kind==='costume'?COSTUME_ITEMS:ACCESSORY_ITEMS,item=list.find(i=>i.id===id);if(!item||playerLevel()<item.level)return false;const inv=shopInventory(),key=kind+':'+id;if(item.cost&&!inv[key]){if(profile.coins<item.cost){toast('Earn more credits to unlock this item.');return false}profile.coins-=item.cost;inv[key]=true}profile.cosmetics??={outfit:'classic',accessory:'none'};profile.cosmetics[kind==='costume'?'outfit':'accessory']=id;avatarSprites.clear();operatorFrames.clear();save();GameAudio.effect('unlock');creditShop(kind==='costume'?'costumes':'accessories');return true}
const gearCreditShop=creditShop;creditShop=function(tab='armour'){if(!canVisitOutfitShop()){toast('Visit the outfit shop between rounds.');return}if(!['costumes','accessories'].includes(tab)){if(live){creditShop('costumes');return}gearCreditShop(tab);const tabs=document.querySelector('.shop-tabs');tabs?.insertAdjacentHTML('beforeend','<button data-shop-tab="costumes">Outfits & costumes</button><button data-shop-tab="accessories">Accessories</button>');const balance=document.querySelector('.shop-balance');if(balance)balance.innerHTML=balance.innerHTML.replace('/ 50','/ 100');return}const kind=tab==='costumes'?'costume':'accessory',items=kind==='costume'?COSTUME_ITEMS.filter(item=>!['world-cn-jade','world-cn-blossom','world-hk-harbour'].includes(item.id)):ACCESSORY_ITEMS,eq=equippedCosmetic(),inv=shopInventory();openModal(`${topModal('COMPANION OUTFITTERS')}<h2 id="modal-title">Your look. Your achievement.</h2><p class="shop-balance">◆ <b>${profile.coins}</b> earned credits · Level ${playerLevel()} / 100</p><p class="sub">Cosmetic items change appearance. Every purchase uses game credits; no money is charged. The Christmas collection is available as a special festive style.</p><div class="shop-tabs">${['armour','shield','style','costumes','accessories'].map(t=>`<button data-shop-tab="${t}" aria-pressed="${t===tab}">${{armour:'Armour',shield:'Shields',style:'Crests',costumes:'Outfits & costumes',accessories:'Accessories'}[t]}</button>`).join('')}</div><div class="shop-grid">${items.map(item=>{const owned=!item.cost||inv[kind+':'+item.id],active=eq[kind==='costume'?'outfit':'accessory']===item.id,locked=playerLevel()<item.level,look={...eq,[kind==='costume'?'outfit':'accessory']:item.id};return `<article class="shop-item cosmetic-item ${active?'equipped':''}" style="--item-colour:${item.colour}"><button class="cosmetic-model" data-cosmetic-preview="${kind}:${item.id}" aria-label="Enlarge and animate ${item.name}">${heroSVG(profile.hero,'',undefined,undefined,undefined,look)}</button><small>${item.rarity}</small><h3>${item.name}</h3><p>Level ${item.level} · ${owned?'OWNED':item.cost.toLocaleString()+' CREDITS'}</p><button class="${active?'secondary':'primary'}" data-cosmetic-buy="${kind}:${item.id}" ${locked||active||(!owned&&profile.coins<item.cost)?'disabled':''}>${locked?'Unlock at level '+item.level:active?'Equipped ✓':owned?'Equip':'Unlock · '+item.cost.toLocaleString()}</button></article>`}).join('')}</div>`)};
const SOLO_BOOSTS={life:{cost:150,name:'+1 battle heart'},time:{cost:250,name:'+30 seconds'}};
function soloBoostCards(){if(live||!game||quiz||!game.prepared)return'';const used=game.purchasedBoosts||{};return `<section class="solo-boosts"><h3>Optional solo boosts</h3><p>One of each per run · Credits are spent immediately · Unavailable with friends.</p><p><b>This run: ${game.hp} hearts · ${Math.ceil(game.time)} seconds remaining</b></p><div>${Object.entries(SOLO_BOOSTS).map(([id,b])=>`<button class="secondary" data-solo-boost="${id}" ${used[id]||profile.coins<b.cost?'disabled':''}>${used[id]?'✓ Purchased':b.name+' · '+b.cost+' credits'}</button>`).join('')}</div>${game.alt?.type==='dodge'?'<small>Extra time also extends the storm’s survival duration.</small>':''}</section>`}
function buySoloBoost(id){const g=game,b=SOLO_BOOSTS[id];if(!g||live||quiz||!g.prepared||!b||g.hp<=0)return false;g.purchasedBoosts??={};if(g.purchasedBoosts[id]||profile.coins<b.cost)return false;profile.coins-=b.cost;g.purchasedBoosts[id]=true;if(id==='life'){g.hp++;g.maxHp++}else{g.time+=30;g.maxTime=(g.maxTime||g.time-30)+30}save();GameAudio.effect('pickup');if(id==='life'&&document.querySelector('.loadout-results'))document.querySelector('#modal-title').textContent=g.hp+' hearts ready.';const existing=document.querySelector('.solo-boosts');if(existing)existing.outerHTML=soloBoostCards();toast(b.name+' added to this run.');return true}
const boostedPreparation=preparationResults;preparationResults=function(){boostedPreparation();if(!live)document.querySelector('.loadout-results')?.insertAdjacentHTML('beforeend',soloBoostCards())};
const boostedPause=pause;pause=function(){boostedPause();if(!live)document.querySelector('#modal-content')?.insertAdjacentHTML('beforeend',soloBoostCards())};
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.cosmeticBuy){event.preventDefault();event.stopImmediatePropagation();buyCosmetic(...b.dataset.cosmeticBuy.split(':'))}if(b.dataset.soloBoost){event.preventDefault();event.stopImmediatePropagation();buySoloBoost(b.dataset.soloBoost)}},true);
const cosmeticMerge=mergeLivePlayers;mergeLivePlayers=function(){cosmeticMerge();if(live)for(const p of live.players)if(live.units[p.id])live.units[p.id].cosmetic=p.state?.cosmetic||{outfit:'classic',accessory:'none'}};
const cosmeticState=liveAPI;liveAPI=function(action,body={}){if(action==='sync'&&body.state)body={...body,state:{...body.state,cosmetic:equippedCosmetic()}};return cosmeticState(action,body)};
